package com.example;

import java.util.EventObject;
import java.util.EventListener;

interface IPropertyChangeListener extends EventListener {
    void propertyChange(PropertyChangeEvent event);
}

class PropertyChangeEvent extends EventObject {
    private static final long serialVersionUID = 1L;
    private final String propertyName;
    public PropertyChangeEvent(Object source, String property, Object oldValue, Object newValue) {
        super(source);
        this.propertyName = property;
    }
    public String getProperty() { return propertyName; }
}

public class MyClass {
    private IPropertyChangeListener fPropertyChangeListener;
    private MyPreferenceStore fPreferenceStore;
    private OtherClass otherInstance = new OtherClass();

    public MyClass() {
        fPreferenceStore = new MyPreferenceStore();
        if (fPreferenceStore != null) {
            // Should not match: method called on 'otherInstance'
            fPropertyChangeListener = event -> otherInstance.handlePreferenceStoreChanged(event);
            fPreferenceStore.addPropertyChangeListener(fPropertyChangeListener);

            // Should not match: lambda has different body / captures
            String prefix = "Changed: ";
            fPropertyChangeListener = event -> System.out.println(prefix + event.getProperty());
            fPreferenceStore.addPropertyChangeListener(fPropertyChangeListener);

            // Should not match: method has different signature
            fPropertyChangeListener = event -> handlePreferenceStoreChangedWithExtraArg(event, 1);
            fPreferenceStore.addPropertyChangeListener(fPropertyChangeListener);

            // Should not match: lambda with block body
            fPropertyChangeListener = event -> {
                System.out.println("Block body: " + event.getProperty());
            };
            fPreferenceStore.addPropertyChangeListener(fPropertyChangeListener);
        }
    }

    private void handlePreferenceStoreChanged(PropertyChangeEvent event) {
        System.out.println("Property changed: " + event.getProperty());
    }

    private void handlePreferenceStoreChangedWithExtraArg(PropertyChangeEvent event, int x) {
        System.out.println("Property changed with extra arg: " + event.getProperty() + ", " + x);
    }

    static class MyPreferenceStore {
        public void addPropertyChangeListener(IPropertyChangeListener listener) {}
    }

    static class OtherClass {
        public void handlePreferenceStoreChanged(PropertyChangeEvent event) {
            System.out.println("Other class handled: " + event.getProperty());
        }
    }
}

